//! Third-party notice tests. The app and the command ship open-source
//! crates whose licences ask for their notices to be kept with every copy.
//! `THIRD-PARTY-NOTICES.md` holds them, generated by
//! `scripts/third-party-notices.sh` (cargo-about) from `Cargo.lock`; the
//! app shows it in its About panel and bundle, the command prints it with
//! `-licenses`, and the release script ships it and refuses a stale copy.
//!
//! These tests check, without cargo-about, that the file lists every crate
//! in `Cargo.lock` at its locked version, and nothing else, so a dependency
//! change can't land without regenerating it; and that the script runs only
//! with the pinned cargo-about and fetches the locked crates first. Only
//! `std` is used.

mod common;

use common::shell::{code_lines, first_line_with};
use common::{read, repo_root};
use std::collections::BTreeSet;

const NOTICES: &str = "THIRD-PARTY-NOTICES.md";

/// The script that writes the notices, relative to the repository root.
const SCRIPT: &str = "scripts/third-party-notices.sh";

/// The cargo-about version the notices are written with.
const ABOUT_VERSION: &str = "0.9.3";

/// The crates.io packages in `Cargo.lock`, as `name version`.
fn locked_packages() -> BTreeSet<String> {
    let lock = read(&repo_root().join("Cargo.lock"));
    let mut out = BTreeSet::new();
    for block in lock.split("[[package]]").skip(1) {
        let field = |key: &str| {
            block.lines().find_map(|l| {
                l.strip_prefix(&format!("{key} = \""))
                    .and_then(|v| v.strip_suffix('"'))
                    .map(str::to_owned)
            })
        };
        // Workspace crates have no source.
        if field("source").is_some() {
            let name = field("name").expect("a package has a name");
            let version = field("version").expect("a package has a version");
            out.insert(format!("{name} {version}"));
        }
    }
    out
}

/// The crates the notices list under their licences: the `- `name version``
/// lines.
fn listed_packages(text: &str) -> BTreeSet<String> {
    text.lines()
        .filter_map(|l| l.strip_prefix("- `"))
        .filter_map(|l| l.strip_suffix('`'))
        .map(str::to_owned)
        .collect()
}

fn notices() -> String {
    let path = repo_root().join(NOTICES);
    assert!(
        path.is_file(),
        "{NOTICES} must exist; run scripts/third-party-notices.sh"
    );
    read(&path)
}

#[test]
fn the_notices_say_how_they_are_made() {
    let text = notices();
    assert!(
        text.starts_with("# Third-party notices\n"),
        "{NOTICES} title"
    );
    assert!(
        text.contains("scripts/third-party-notices.sh"),
        "{NOTICES} must name the script that writes it"
    );
}

#[test]
fn the_notices_list_every_locked_crate() {
    let listed = listed_packages(&notices());
    let missing: Vec<String> = locked_packages().difference(&listed).cloned().collect();
    assert!(
        missing.is_empty(),
        "{NOTICES} is out of date (run scripts/third-party-notices.sh); missing:\n  {}",
        missing.join("\n  ")
    );
}

#[test]
fn the_notices_list_only_locked_crates() {
    let listed = listed_packages(&notices());
    let stale: Vec<String> = listed.difference(&locked_packages()).cloned().collect();
    assert!(
        stale.is_empty(),
        "{NOTICES} is out of date (run scripts/third-party-notices.sh); not in Cargo.lock:\n  {}",
        stale.join("\n  ")
    );
}

#[test]
fn the_notices_hold_the_licence_texts() {
    let text = notices();
    for phrase in [
        "Permission is hereby granted, free of charge",
        "UNICODE LICENSE V3",
    ] {
        assert!(
            text.contains(phrase),
            "{NOTICES} must hold the licence text with {phrase:?}"
        );
    }
}

/// A crate published without a copyright line gets the licence's
/// placeholder ("<copyright holders>") from cargo-about. Each such crate is
/// named, with its project's real copyright holders, in the section that
/// `about.hbs` adds for them.
#[test]
fn placeholder_copyrights_are_named() {
    let text = notices();
    let heading = "## Copyright notices for crates published without one";
    let named = text
        .split_once(heading)
        .map(|(_, rest)| rest.split("\n## ").next().unwrap_or(""))
        .unwrap_or_else(|| panic!("{NOTICES} must have the section {heading:?}"));
    let mut unnamed = Vec::new();
    for section in text
        .split("\n## ")
        .filter(|s| s.contains("<copyright holders>"))
    {
        for crate_line in section.lines().filter_map(|l| l.strip_prefix("- `")) {
            let Some(name) = crate_line
                .strip_suffix('`')
                .and_then(|c| c.split(' ').next())
            else {
                continue;
            };
            let windows_target = name.starts_with("windows_") && named.contains("`windows_*`");
            if !named.contains(&format!("`{name}`")) && !windows_target {
                unnamed.push(name.to_owned());
            }
        }
    }
    assert!(
        unnamed.is_empty(),
        "crates under a placeholder copyright not named in about.hbs's section:\n  {}",
        unnamed.join("\n  ")
    );
}

// ---------------------------------------------------------------------------
// The script.
// ---------------------------------------------------------------------------

/// Another cargo-about version words or orders the file differently, so
/// `--check` would fail on current notices (or pass stale ones): the
/// script pins the version and says how to install it. It runs cargo-about
/// offline (`--frozen`), so it fetches the locked crates first, on a fresh
/// machine too.
#[test]
fn script_pins_cargo_about_and_fetches_the_locked_crates_first() {
    let text = read(&repo_root().join(SCRIPT));
    assert!(
        text.contains(&format!("ABOUT_VERSION={ABOUT_VERSION}\n")),
        "{SCRIPT} must pin cargo-about {ABOUT_VERSION}"
    );
    let code = code_lines(&text);
    let line = |needle: &str| {
        first_line_with(&code, needle).unwrap_or_else(|| panic!("{SCRIPT} must run {needle:?}"))
    };
    let version = line("cargo about --version");
    let fetch = line("cargo fetch --locked");
    let generate = line("cargo about generate");
    assert!(
        version < fetch && fetch < generate,
        "{SCRIPT} must check cargo-about's version, then fetch, then generate"
    );
    assert!(
        text.contains("cargo install cargo-about --locked --features cli --version $ABOUT_VERSION"),
        "{SCRIPT} must say how to install the pinned cargo-about"
    );
}

#[cfg(unix)]
mod behaviour {
    use super::*;
    use common::shell::{SYSTEM_PATH, assert_refused, describe, run_with_timeout, temp_path};
    use std::fs;
    use std::os::unix::fs::PermissionsExt;
    use std::path::{Path, PathBuf};
    use std::process::{Command, Output};

    /// A copy of the script in a fresh folder, with fake `cargo` and
    /// `cargo-about` commands; `cargo` logs its arguments to `calls.log`,
    /// prints `cargo-about <version>` for `cargo about --version` and exits
    /// with `fetch_status` for `cargo fetch --locked`.
    struct Fixture {
        dir: PathBuf,
    }

    impl Fixture {
        fn new(tag: &str, version: &str, fetch_status: i32) -> Fixture {
            let dir = temp_path(tag);
            fs::create_dir_all(dir.join("repo/scripts")).unwrap();
            fs::create_dir_all(dir.join("bin")).unwrap();
            fs::write(
                dir.join("repo").join(SCRIPT),
                read(&repo_root().join(SCRIPT)),
            )
            .unwrap();
            let log = dir.join("calls.log");
            let cargo = format!(
                "#!/bin/sh\necho \"$*\" >>'{}'\n\
                 case \"$1 $2\" in\n\
                 'about --version') echo 'cargo-about {version}' ;;\n\
                 'fetch --locked') exit {fetch_status} ;;\n\
                 *) exit 0 ;;\n\
                 esac\n",
                log.display()
            );
            write_tool(&dir.join("bin/cargo"), &cargo);
            write_tool(&dir.join("bin/cargo-about"), "#!/bin/sh\nexit 0\n");
            Fixture { dir }
        }

        fn run(&self) -> Output {
            let path = format!("{}:{SYSTEM_PATH}", self.dir.join("bin").display());
            run_with_timeout(
                Command::new("sh")
                    .arg(self.dir.join("repo").join(SCRIPT))
                    .arg("--check")
                    .env("PATH", path),
            )
        }

        fn calls(&self) -> String {
            fs::read_to_string(self.dir.join("calls.log")).unwrap_or_default()
        }
    }

    impl Drop for Fixture {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.dir);
        }
    }

    fn write_tool(path: &Path, script: &str) {
        fs::write(path, script).unwrap();
        fs::set_permissions(path, fs::Permissions::from_mode(0o755)).unwrap();
    }

    #[test]
    fn refuses_another_cargo_about_version() {
        let fixture = Fixture::new("about-version", "0.9.2", 0);
        let out = fixture.run();
        assert_refused(&out, 1, ABOUT_VERSION, "cargo-about 0.9.2");
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(
            stderr.contains("cargo install cargo-about"),
            "{}",
            describe(&out)
        );
        let calls = fixture.calls();
        assert!(
            !calls.contains("fetch") && !calls.contains("generate"),
            "nothing runs after a version mismatch: {calls}"
        );
    }

    /// cargo finds its subcommands in `~/.cargo/bin` even when that folder
    /// isn't on the shell's PATH, so the script asks `cargo about --version`
    /// rather than looking for a `cargo-about` command on PATH.
    #[test]
    fn finds_cargo_about_through_cargo() {
        let fixture = Fixture::new("about-through-cargo", ABOUT_VERSION, 101);
        fs::remove_file(fixture.dir.join("bin/cargo-about")).unwrap();
        let out = fixture.run();
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(!stderr.contains("not installed"), "{}", describe(&out));
        let calls = fixture.calls();
        assert!(
            calls.contains("fetch --locked"),
            "the version check passes and the script goes on: {calls}"
        );
    }

    #[test]
    fn stops_when_the_locked_crates_cannot_be_fetched() {
        let fixture = Fixture::new("about-fetch", ABOUT_VERSION, 101);
        let out = fixture.run();
        assert_refused(&out, 1, "cargo fetch --locked", "a failed fetch");
        let calls = fixture.calls();
        assert!(calls.contains("fetch --locked"), "{calls}");
        assert!(
            !calls.contains("generate"),
            "nothing is generated after a failed fetch: {calls}"
        );
    }
}
